import { useIonViewWillEnter } from '@ionic/react';

const toHermosillo = (utc: string | undefined): string => {
  if (!utc) return '';
  const d = new Date(utc.includes('Z') ? utc : utc + 'Z');
  return new Date(d.getTime() - 7 * 60 * 60 * 1000).toLocaleString();
};

interface PosRewardCatalogItemFormState {
  name: string;
  rewardType: 'DISCOUNT' | 'FREE_PRODUCT' | '';
  requiredPoints: string;
  discountValue: string;
  freeProductId: string;
  isActive: boolean;
  description: string;
}

const PosRewardCatalogItemPage: React.FC = () => {
  const { companyId } = useUser();

  const [posRewardCatalogItems, setPosRewardCatalogItems] = useState<PosRewardCatalogItem[]>([]);
  const [filteredPosRewardCatalogItems, setFilteredPosRewardCatalogItems] = useState<PosRewardCatalogItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [showToast, setShowToast] = useState(false);
  const [toastMessage, setToastMessage] = useState('');
  const [toastColor, setToastColor] = useState<'success' | 'danger' | 'warning' | undefined>(undefined);

  const [showModal, setShowModal] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [currentCatalogItem, setCurrentCatalogItem] = useState<PosRewardCatalogItem | null>(null);
  const [formState, setFormState] = useState<PosRewardCatalogItemFormState>({
    name: '',
    rewardType: '',
    requiredPoints: '',
    discountValue: '',
    freeProductId: '',
    isActive: true,
    description: '',
  });

  const [nameError, setNameError] = useState('');
  const [rewardTypeError, setRewardTypeError] = useState('');
  const [requiredPointsError, setRequiredPointsError] = useState('');
  const [discountValueError, setDiscountValueError] = useState('');
  const [freeProductIdError, setFreeProductIdError] = useState('');

  const [showDeleteAlert, setShowDeleteAlert] = useState(false);
  const [itemToDelete, setItemToDelete] = useState<PosRewardCatalogItem | null>(null);

  const [searchTerm, setSearchTerm] = useState('');
  const [displayedItemsCount, setDisplayedItemsCount] = useState(20);

  const [popoverState, setPopoverState] = useState<{
    showAlertPopover: boolean;
    showMailPopover: boolean;
    event?: Event;
  }>({ showAlertPopover: false, showMailPopover: false });

  const presentAlertPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showAlertPopover: true, event: e.nativeEvent });
  const dismissAlertPopover = () =>
    setPopoverState({ ...popoverState, showAlertPopover: false });
  const presentMailPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showMailPopover: true, event: e.nativeEvent });
  const dismissMailPopover = () =>
    setPopoverState({ ...popoverState, showMailPopover: false });

  const fetchPosRewardCatalogItems = async () => {
    setLoading(true);
    setError('');
    try {
      const data = await getAllPosRewardCatalogItems(companyId);
      setPosRewardCatalogItems(data);
      setFilteredPosRewardCatalogItems(data.filter(item =>
        item.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        item.rewardType.toLowerCase().includes(searchTerm.toLowerCase()) ||
        item.description?.toLowerCase().includes(searchTerm.toLowerCase())
      ));
      setDisplayedItemsCount(20); // Reset count on new fetch
    } catch (err) {
      setError((err as Error).message ?? 'Error al cargar los ítems del catálogo de recompensas.');
      setToastMessage('Error al cargar los ítems del catálogo.');
      setToastColor('danger');
      setShowToast(true);
    } finally {
      setLoading(false);
    }
  };

  useIonViewWillEnter(() => {
    fetchPosRewardCatalogItems();
  }, [companyId]);

  useEffect(() => {
    // Filter on search term change
    setFilteredPosRewardCatalogItems(posRewardCatalogItems.filter(item =>
      item.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.rewardType.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.description?.toLowerCase().includes(searchTerm.toLowerCase())
    ));
    setDisplayedItemsCount(20);
  }, [searchTerm, posRewardCatalogItems]);

  const loadMoreItems = (ev: CustomEvent<void>) => {
    setTimeout(() => {
      setDisplayedItemsCount(prevCount => prevCount + 20);
      (ev.target as HTMLIonInfiniteScrollElement).complete();
    }, 500);
  };

  const handleCreateClick = () => {
    setIsEditing(false);
    setCurrentCatalogItem(null);
    setFormState({
      name: '',
      rewardType: '',
      requiredPoints: '',
      discountValue: '',
      freeProductId: '',
      isActive: true,
      description: '',
    });
    resetFormErrors();
    setShowModal(true);
  };

  const handleEditClick = (item: PosRewardCatalogItem) => {
    setIsEditing(true);
    setCurrentCatalogItem(item);
    setFormState({
      name: item.name,
      rewardType: item.rewardType,
      requiredPoints: item.requiredPoints.toFixed(2),
      discountValue: item.discountValue !== null ? item.discountValue.toFixed(2) : '',
      freeProductId: item.freeProductId !== null ? String(item.freeProductId) : '',
      isActive: item.isActive,
      description: item.description || '',
    });
    resetFormErrors();
    setShowModal(true);
  };

  const handleModalDismiss = () => {
    setShowModal(false);
    resetFormErrors();
  };

  const handleInputChange = (e: CustomEvent<InputInputEventDetail>) => {
    const { name, value } = e.target as HTMLIonInputElement;
    setFormState(prev => ({ ...prev, [name!]: value! }));
    // Reset specific error on input
    switch (name) {
      case 'name': setNameError(''); break;
      case 'requiredPoints': setRequiredPointsError(''); break;
      case 'discountValue': setDiscountValueError(''); break;
      case 'freeProductId': setFreeProductIdError(''); break;
    }
  };

  const handleRewardTypeChange = (e: CustomEvent<SelectChangeEventDetail>) => {
    const value = e.detail.value as 'DISCOUNT' | 'FREE_PRODUCT' | '';
    setFormState(prev => ({
      ...prev,
      rewardType: value,
      discountValue: value === 'DISCOUNT' ? prev.discountValue : '',
      freeProductId: value === 'FREE_PRODUCT' ? prev.freeProductId : '',
    }));
    setRewardTypeError('');
    setDiscountValueError('');
    setFreeProductIdError('');
  };

  const handleToggleChange = (e: CustomEvent<ToggleChangeEventDetail>) => {
    setFormState(prev => ({ ...prev, isActive: e.detail.checked }));
  };

  const validateForm = () => {
    let isValid = true;
    if (!formState.name.trim()) {
      setNameError('El nombre es requerido.');
      isValid = false;
    } else { setNameError(''); }

    if (!formState.rewardType) {
      setRewardTypeError('El tipo de recompensa es requerido.');
      isValid = false;
    } else { setRewardTypeError(''); }

    const parsedPoints = parseFloat(formState.requiredPoints);
    if (isNaN(parsedPoints) || parsedPoints <= 0) {
      setRequiredPointsError('Los puntos requeridos deben ser un número positivo.');
      isValid = false;
    } else { setRequiredPointsError(''); }

    if (formState.rewardType === 'DISCOUNT') {
      const parsedDiscount = parseFloat(formState.discountValue);
      if (isNaN(parsedDiscount) || parsedDiscount <= 0) {
        setDiscountValueError('El valor del descuento debe ser un número positivo.');
        isValid = false;
      } else { setDiscountValueError(''); }
    } else { setDiscountValueError(''); }

    if (formState.rewardType === 'FREE_PRODUCT') {
      const parsedProductId = parseInt(formState.freeProductId, 10);
      if (isNaN(parsedProductId) || parsedProductId <= 0) {
        setFreeProductIdError('El ID del producto debe ser un número entero positivo.');
        isValid = false;
      } else { setFreeProductIdError(''); }
    } else { setFreeProductIdError(''); }

    return isValid;
