      const payload = {
        companyId,
        name: formState.name,
        rewardType: formState.rewardType as 'DISCOUNT' | 'FREE_PRODUCT',
        requiredPoints: parseFloat(formState.requiredPoints),
        discountValue: formState.rewardType === 'DISCOUNT' ? parseFloat(formState.discountValue) : null,
        freeProductId: formState.rewardType === 'FREE_PRODUCT' ? parseInt(formState.freeProductId, 10) : null,
        isActive: formState.isActive,
        description: formState.description || null,
      };

