        await createPosRewardCatalogItem(payload);
        setToastMessage('¡Ítem de catálogo de recompensa creado con éxito!');
        setToastColor('success');
      }
      setShowToast(true);
      setShowModal(false);
      fetchPosRewardCatalogItems();
    } catch (err) {
      setError((err as Error).message ?? 'Error desconocido al guardar.');
      setToastMessage(`Error: ${(err as Error).message ?? 'Error desconocido.'}`);
      setToastColor('danger');
      setShowToast(true);
    } finally {
      setSaving(false);
    }
  };

