    if (!itemToDelete) return;

    setLoading(true);
    setError('');
    try {
      await deletePosRewardCatalogItem(itemToDelete.catalogItemId, companyId);
      setToastMessage('¡Ítem de catálogo de recompensa eliminado con éxito!');
      setToastColor('success');
      setShowToast(true);
      fetchPosRewardCatalogItems();
    } catch (err) {
      setError((err as Error).message ?? 'Error desconocido al eliminar.');
      setToastMessage(`Error: ${(err as Error).message ?? 'Error desconocido.'}`);
      setToastColor('danger');
      setShowToast(true);
    } finally {
      setLoading(false);
      setItemToDelete(null);
