              <IonButton slot="end" onClick={handleModalDismiss} fill="clear">
                <IonIcon icon={closeCircle} slot="icon-only" />
              </IonButton>
            </IonToolbar>
          </IonHeader>
          <IonContent className="ion-padding">
            <div className="posrewardcatalogitem-form-fields">
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Nombre *"
                  labelPlacement="floating"
                  name="name"
                  value={formState.name}
                  onIonInput={handleInputChange}
                  className={nameError ? 'ion-invalid ion-touched' : ''}
                  errorText={nameError}
                />
              </div>

              <div className="wizard-field-group">
                <IonSelect
                  fill="outline"
                  label="Tipo de Recompensa *"
                  labelPlacement="floating"
                  value={formState.rewardType}
                  onIonChange={handleRewardTypeChange}
                  className={rewardTypeError ? 'ion-invalid ion-touched' : ''}
                  errorText={rewardTypeError}
                >
                  <IonSelectOption value="DISCOUNT">Descuento</IonSelectOption>
                  <IonSelectOption value="FREE_PRODUCT">Producto Gratuito</IonSelectOption>
                </IonSelect>
              </div>

              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Puntos Requeridos *"
                  labelPlacement="floating"
                  name="requiredPoints"
                  type="number"
                  value={formState.requiredPoints}
                  onIonInput={handleInputChange}
                  className={requiredPointsError ? 'ion-invalid ion-touched' : ''}
                  errorText={requiredPointsError}
                />
              </div>

              {formState.rewardType === 'DISCOUNT' && (
                <div className="wizard-field-group">
                  <IonInput
                    fill="outline"
                    label="Valor del Descuento *"
                    labelPlacement="floating"
                    name="discountValue"
                    type="number"
                    value={formState.discountValue}
                    onIonInput={handleInputChange}
                    className={discountValueError ? 'ion-invalid ion-touched' : ''}
                    errorText={discountValueError}
                  />
                </div>
              )}

              {formState.rewardType === 'FREE_PRODUCT' && (
                <div className="wizard-field-group">
                  <IonInput
                    fill="outline"
                    label="ID del Producto Gratuito *"
                    labelPlacement="floating"
                    name="freeProductId"
                    type="number"
                    value={formState.freeProductId}
                    onIonInput={handleInputChange}
                    className={freeProductIdError ? 'ion-invalid ion-touched' : ''}
                    errorText={freeProductIdError}
                  />
                </div>
              )}

              <div className="wizard-field-group">
                <IonToggle
                  checked={formState.isActive}
                  onIonChange={handleToggleChange}
                  justify="space-between"
                  className="posrewardcatalogitem-modal-toggle"
                >
                  Activo
                </IonToggle>
              </div>

              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Descripción"
                  labelPlacement="floating"
                  name="description"
                  value={formState.description}
                  onIonInput={handleInputChange}
                />
              </div>
            </div>

            <IonButton expand="block" onClick={handleSave} disabled={saving} className="ion-margin-top">
              {saving ? <IonSpinner name="dots" /> : (isEditing ? 'Actualizar' : 'Crear')}
            </IonButton>
          </IonContent>
        </IonModal>

        <IonAlert
          isOpen={showDeleteAlert}
          onDidDismiss={() => setShowDeleteAlert(false)}
          header={'Confirmar Eliminación'}
          message={`¿Estás seguro de que quieres eliminar la recompensa "${itemToDelete?.name}"?`}
          buttons={[
            { text: 'Cancelar', role: 'cancel' },
            { text: 'Eliminar', handler: confirmDelete, cssClass: 'danger-button' },
          ]}
        />
      </IonContent>
    </IonPage>
  );
};

export default PosRewardCatalogItemPage;
